-- Reversao segura, POS-APPLY, da manutencao do campo explicacao de
-- Q180/Q181/Q182 (cc92) e Q189/Q190/Q191 (cc94), DH-AUT-06.
--
-- NAO EXECUTAR agora. Este arquivo so devera ser usado se, no futuro,
-- for necessario desfazer a manutencao ja confirmada (commit) de
-- supabase/manutencao_dh_aut_06_cc92_cc94.sql, restaurando literalmente
-- os textos corrompidos que estavam em producao antes dessa manutencao.
--
-- Mecanismo de identificacao: cada UPDATE so afeta a linha se o hash
-- md5 da explicacao atual bater exatamente com o hash NOVO (pos-
-- manutencao) auditado, E o fingerprint imutavel (id+enunciado+
-- dificuldade+ativa+alternativas) continuar identico ao congelado —
-- garantindo que nenhuma alteracao concorrente de outro campo tenha
-- ocorrido desde a aplicacao. NAO usa DELETE nem UPDATE amplo por
-- materia_id/assunto_id/unidade — atinge exclusivamente as 6 linhas
-- cujo id e cujo hash de explicacao batem com o esperado.
--
-- Textos antigos representados em base64 (decode + convert_from),
-- reproduzindo byte a byte — inclusive as quebras de linha CRLF
-- originais — o conteudo que estava em producao antes da manutencao.
--
-- Termina em COMMIT. So deve ser executado apos autorizacao humana
-- explicita, e apos novo teste_rollback proprio (nao incluido aqui,
-- pois este arquivo e de uso excepcional/pos-apply, nao parte do fluxo
-- normal de manutencao).

begin;

set local request.jwt.claim.sub = 'e5523807-6cc8-4867-8a56-77c17552e56e';

create temporary table _lote_reversao (
  ordem int primary key,
  questao_id bigint,
  new_md5 text,
  old_md5 text,
  fingerprint text,
  texto_base64 text
) on commit drop;

insert into _lote_reversao (ordem, questao_id, new_md5, old_md5, fingerprint, texto_base64) values
(1, 180, 'c189e7cb437586cc94cae1de61903cae', '4ace86b95f26fd0f077c3f312669f96f', 'ba1190ee35c21e754efd72188b1831ed',
 ''),
(2, 181, '950ddb18cfb2857907c09b7297751cf8', '30858e94c4ac4d6203c6615cdf9b1fab', 'e5954ed8514c572e0ca1ed50c6bd14a4',
 ''),
(3, 182, 'a6033d457b0f9e24528ba2245d3fdb38', 'c64cf9fd654bc2ed71261935c8fc79dc', '0ef612cc4ab918bb2b0785c1a7731d19',
 ''),
(4, 189, '214e0ec3a8ee94a22e39e16abd5398c5', 'c7bfa453bb11f933260036c92e837063', '9241e23edeaeb79e0d594eed8ecf028f',
 ''),
(5, 190, '5f0a106956022042a6a212904b4ff65b', '83d40871e689b73773e6399ab85c2deb', 'e762471c699ff3186dbf21370de289c9',
 ''),
(6, 191, '06d4e174f2db3310fec46b97c14e69d6', '687b0faf0f5e980c3842c2da502b5cd9', 'fdf216411ced3f5f58a68d28be58da75',
 '');

do $$
declare
  v_cnt int;
begin
  select count(*) into v_cnt
  from _lote_reversao lr
  join public.questoes q on q.id = lr.questao_id
  where md5(coalesce(q.explicacao,'')) = lr.new_md5
    and md5(
      concat_ws('|', q.id::text, q.enunciado, q.dificuldade, q.ativa::text,
        (select string_agg(ordem::text || ':' || texto || ':' || correta::text, '||' order by ordem)
           from public.alternativas a where a.questao_id = q.id))
    ) = lr.fingerprint;
  if v_cnt <> 6 then
    raise exception 'Abortado: apenas % de 6 questao(oes) conferem simultaneamente new_md5 e fingerprint — nao reverter as cegas', v_cnt;
  end if;
end $$;

do $$
declare r record; v_rows int;
begin
  for r in select * from _lote_reversao order by ordem loop
    update public.questoes
    set explicacao = convert_from(decode(r.texto_base64, 'base64'), 'UTF8')
    where id = r.questao_id
      and md5(coalesce(explicacao,'')) = r.new_md5
      and md5(
        concat_ws('|', id::text, enunciado, dificuldade, ativa::text,
          (select string_agg(ordem::text || ':' || texto || ':' || correta::text, '||' order by ordem)
             from public.alternativas a where a.questao_id = questoes.id))
      ) = r.fingerprint;
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'Abortado: reversao de questao_id=% afetou % linha(s), esperado exatamente 1 — nao reverter as cegas', r.questao_id, v_rows;
    end if;
  end loop;
end $$;

do $$
declare
  v_cnt int;
begin
  select count(*) into v_cnt from public.questoes
  where id in (180,181,182,189,190,191)
    and md5(coalesce(explicacao,'')) in (
      '4ace86b95f26fd0f077c3f312669f96f','30858e94c4ac4d6203c6615cdf9b1fab','c64cf9fd654bc2ed71261935c8fc79dc',
      'c7bfa453bb11f933260036c92e837063','83d40871e689b73773e6399ab85c2deb','687b0faf0f5e980c3842c2da502b5cd9'
    );
  if v_cnt <> 6 then
    raise exception 'Abortado: apos reversao, esperado exatamente 6 questoes com os hashes originais, encontrado %', v_cnt;
  end if;
end $$;

commit;
